import{_ as e,c as r,o as t,al as l}from"./chunks/framework.D8UyiDWg.js";const p=JSON.parse('{"title":"机体类型与设置","description":"","frontmatter":{},"headers":[],"relativePath":"zh/airframes/index.md","filePath":"zh/airframes/index.md"}'),i={name:"zh/airframes/index.md"};function o(s,a,n,f,h,m){return t(),r("div",null,a[0]||(a[0]=[l('<h1 id="机体类型与设置" tabindex="-1">机体类型与设置 <a class="header-anchor" href="#机体类型与设置" aria-label="Permalink to &quot;机体类型与设置&quot;">​</a></h1><p>PX4 支持多种类型的机体，包括不同配置的多旋翼、固定翼、垂直起降、地面车辆等。</p><p>本节解释如何对每种类型进行组装、配置和调整 PX4 基础自动化系统 (大部分的配置是通用的)。</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><a href="./../getting_started/px4_basic_concepts.html#drone-types">基本概念 &gt; 无人机类型</a> 提供了不同类型的机体以及相关机体的最佳使用场景的高级信息。</p></div><h2 id="支持的载具" tabindex="-1">支持的载具 <a class="header-anchor" href="#支持的载具" aria-label="Permalink to &quot;支持的载具&quot;">​</a></h2><p>有维护者且经过良好测试和支持的机架类型是：</p><ul><li><a href="./../frames_multicopter/">多旋翼</a> (三轴， 四轴，十六轴，八轴，甚至 <a href="./../frames_multicopter/omnicopter.html">全向多旋翼</a> 机体)</li><li><a href="./../frames_plane/">飞机 (固定翼)</a></li><li><a href="./../frames_vtol/">VTOL</a>: <a href="./../frames_vtol/standardvtol.html">Standard VTOL</a>, <a href="./../frames_vtol/tailsitter.html">Tailsitter VTOL</a>, <a href="./../frames_vtol/tiltrotor.html">Tiltrotor VTOL</a></li></ul><h2 id="实验机体" tabindex="-1">实验机体 <a class="header-anchor" href="#实验机体" aria-label="Permalink to &quot;实验机体&quot;">​</a></h2><p>实验机架指以下机体种类：</p><ul><li>没有维护者。</li><li>核心开发小组没有定期进行测试。</li><li>可能没有 CI 测试。</li><li>可能缺少量产机体所需的功能。</li><li>可能不支持该机体类型的某些通用配置。</li></ul><p>以下载具类型被认为是试验性的：</p><ul><li><a href="./../frames_airship/">飞艇</a></li><li><a href="./../frames_autogyro/">自旋翼机</a></li><li><a href="./../frames_balloon/">热气球</a></li><li><a href="./../frames_helicopter/">直升机</a></li><li><a href="./../frames_rover/">无人车</a></li><li><a href="./../frames_sub/">潜艇</a></li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Maintainer volunteers, <a href="./../contribute/">contribution</a> of new features, new frame configurations, or other improvements would all be very welcome!</p></div><h2 id="其他载具" tabindex="-1">其他载具 <a class="header-anchor" href="#其他载具" aria-label="Permalink to &quot;其他载具&quot;">​</a></h2><p>全部可支持的机型以及相关配置可见 <a href="./../airframes/airframe_reference.html">机架参考</a>。</p>',15)]))}const d=e(i,[["render",o]]);export{p as __pageData,d as default};
